<!doctype html><html lang="en"><meta charset="utf-8"><title>Write post</title><main><h1>Write a post</h1><p><a href="<?= site_url('admin') ?>">Dashboard</a></p><?php if (! empty($errors)): ?><ul><?php foreach ($errors as $error): ?><li><?= esc($error) ?></li><?php endforeach; ?></ul><?php endif; ?><form method="post"><?= csrf_field() ?><label>Title <input name="title" required maxlength="255" value="<?= old('title') ?>"></label><label>Content <textarea name="content" rows="12"><?= old('content') ?></textarea></label><label><input type="checkbox" name="draft" value="1"> Save as draft</label><button>Save post</button></form></main></html>
